begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','solver@example.invalid',now()),('33333333-3333-4333-8333-333333333333','abid.ibn.ashraf@gmail.com',now());
insert into public.profiles(id,username) values('11111111-1111-4111-8111-111111111111','Solver'),('33333333-3333-4333-8333-333333333333','Owner');
create temp table cases(name text primary key,id uuid);grant all on cases to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into cases select 'first',(e->>'id')::uuid from jsonb_array_elements(public.record_online_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":100,"events":[]}')->'candidates') e where e->>'metric'='single';
select public.submit_leaderboard((select id from cases where name='first'));
select throws_ok($$select public.hold_submission((select id from cases where name='first'),'Self hold')$$,'P0001','Administrator access required','Solvers cannot change review state or send admin notices');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select throws_ok($$select public.review_submission((select id from cases where name='first'),false,'')$$,'P0001','Write an explanation for the rejection','Rejection requires a message to the solver');
select throws_ok($$select public.hold_submission((select id from cases where name='first'),' ')$$,'P0001','Explain the investigation hold in 3–500 characters','Holding a result requires a message');
select is(public.hold_submission((select id from cases where name='first'),'We are checking possible macro use.')->>'status','investigating','A hold creates a distinct private investigation state');
select is(exists(select 1 from jsonb_array_elements(public.inspect_leaderboard_recovery((select id::text from cases where name='first'))->'flags') f where f->>'code'='investigating'),true,'Manual recovery discloses an existing investigation');
select is((public.review_queue()->0->>'status'),'investigating','The review queue exposes held state');
select is((public.review_queue()->0->>'investigation_note'),'We are checking possible macro use.','The admin can see the current hold message');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(public.my_submission_notifications(),'[]'::jsonb,'Legacy tabs do not receive a hold that they would mistake for rejection');
select is(public.my_submission_notifications(true)->0->>'decision','held','Solver receives a hold notification');
select public.mark_submission_notifications_read(array[(public.my_submission_notifications(true)->0->>'id')::bigint]);
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select public.hold_submission((select id from cases where name='first'),'We are checking possible macro use.');
set local role postgres;
select is((select count(*)::int from public.submission_notifications),1,'Repeated hold click does not duplicate notifications');
select is((select read_at is not null from public.submission_notifications),true,'Repeated identical hold does not reset read state');
set local role authenticated;
select public.hold_submission((select id from cases where name='first'),'Please explain the repeated input pattern.');
set local role postgres;
select is((select count(*)::int from public.submission_notifications),1,'Updating a hold message stays bounded to one current hold notice');
select is((select read_at is null from public.submission_notifications),true,'A changed investigation message becomes unread');
set local role anon;
select is((select count(*)::int from public.leaderboard('single')),0,'Investigating results remain off the public leaderboard');
select throws_ok($$select public.hold_submission('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Forged')$$,'42501',null,'Anonymous users cannot send investigation notices');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(public.submit_leaderboard((select id from cases where name='first'))->>'status','investigating','A lost submit response can be retried after an investigation starts');
insert into cases select 'new',(e->>'id')::uuid from jsonb_array_elements(public.record_online_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":90,"events":[]}')->'candidates') e where e->>'metric'='single';
select public.submit_leaderboard((select id from cases where name='new'));
set local role postgres;
select is((select count(*)::int from public.submissions where status='investigating'),1,'Submitting another result does not erase a held investigation');
select is((select count(*)::int from public.submissions where status='pending'),1,'The latest new submission can still await ordinary review');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select public.review_submission((select id from cases where name='first'),true,'Input checked and verified.');
set local role postgres;
select is((select count(*)::int from public.submission_notifications where submission_id=(select id from cases where name='first')),2,'A final decision adds a separate notice after the investigation hold');
set local role authenticated;
select public.hold_submission((select id from cases where name='new'),'We are reviewing the keyboard layout.');
select public.review_submission((select id from cases where name='new'),false,'The keyboard layout encodes an algorithm.');
set local role postgres;
select is((select note from public.submission_notifications where decision='rejected'),'The keyboard layout encodes an algorithm.','Rejection preserves the administrator’s exact explanation');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into cases select 'expired',(e->>'id')::uuid from jsonb_array_elements(public.record_online_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":80,"events":[]}')->'candidates') e where e->>'metric'='single';
select public.submit_leaderboard((select id from cases where name='expired'));
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select public.hold_submission((select id from cases where name='expired'),'Long investigation.');
set local role postgres;
update public.submissions set investigation_at=now()-interval '31 days' where id=(select id from cases where name='expired');
select public.prune_recordings();
select is((select status from public.submissions where id=(select id from cases where name='expired')),'draft','Held cases follow the bounded 30-day review retention policy');
select is((select evidence_refs is null from public.submissions where id=(select id from cases where name='expired')),true,'Expired held evidence is released');
select * from finish();rollback;
